import {
  getProjectDailyReview,
  getProjectDailyReviewPendingDates,
  type ProjectDailyReviewResponse,
  type ProjectDailyReviewPendingDatesResponse,
} from '~/client';

export function useProjectDailyReviewQuery(projectId: Ref<string | undefined>, date: Ref<string>) {
  return useQuery({
    key: () => ['project-daily-review', projectId.value ?? '', date.value],
    query: (): Promise<ProjectDailyReviewResponse> =>
      getProjectDailyReview({
        composable: '$fetch',
        path: { project_id: projectId.value as string },
        query: { date: date.value },
      }),
    enabled: () => Boolean(projectId.value) && Boolean(date.value),
    staleTime: 60_000,
  });
}

export function useProjectDailyReviewPendingDatesQuery(projectId: Ref<string | undefined>) {
  return useQuery({
    key: () => ['project-daily-review-pending-dates', projectId.value ?? ''],
    query: (): Promise<ProjectDailyReviewPendingDatesResponse> =>
      getProjectDailyReviewPendingDates({
        composable: '$fetch',
        path: { project_id: projectId.value as string },
      }),
    enabled: () => Boolean(projectId.value),
    staleTime: 60_000,
  });
}
